- **Step 3: Modify `public/index.html` and `landing/index.html` to fetch API key and handle it**

Let's focus on modifying `public/index.html` first. We'll add the necessary JavaScript to fetch the `/api/client-config` endpoint and handle the API key.

{"name": "edit_file", "arguments": {"path": "public/index.html", "old_string": "<script>", "new_string": "<script>
  fetch('/api/client-config')
    .then(response => response.json())
    .then(config => {
      const apiKey = config.tilerApiKey;
      const basemapConfigured = config.basemapConfigured;

      if (!basemapConfigured) {
        const warningMessage = 'Basemap unavailable: TILER_API_KEY is not configured. See README (Configuration).';
        const warningElement = document.createElement('div');
        warningElement.style.position = 'fixed';
        warningElement.style.bottom = '10px';
        warningElement.style.right = '10px';
        warningElement.style.backgroundColor = 'rgba(255, 0, 0, 0.8)';
        warningElement.style.color = 'white';
        warningElement.style.padding = '10px';
        warningElement.style.borderRadius = '5px';
        warningElement.textContent = warningMessage;
        document.body.appendChild(warningElement);
      }

      if (apiKey) {
        // Append the API key to the tile URLs
        const tileUrls = document.querySelectorAll('[data-tile-url]');
        tileUrls.forEach(tileUrl => {
          tileUrl.href += `?api_key=${apiKey}`;
        });
      }
    })
    .catch(error => console.error('Error fetching client config:', error));

"}}

