  describe('GET /api/client-config', () => {
    it('returns tilerApiKey and basemapConfigured as true when TILER_API_KEY is set', async () => {
      process.env.TILER_API_KEY = 'test-key';
      const res = await request(app).get('/api/client-config');
      expect(res.status).toBe(200);
      expect(res.body.tilerApiKey).toBe('test-key');
      expect(res.body.basemapConfigured).toBe(true);
    });

    it('returns empty tilerApiKey and basemapConfigured as false when TILER_API_KEY is not set', async () => {
      delete process.env.TILER_API_KEY;
      const res = await request(app).get('/api/client-config');
      expect(res.status).toBe(200);
      expect(res.body.tilerApiKey).toBe('');
      expect(res.body.basemapConfigured).toBe(false);
    });
  });

  describe('GET /places/:id', () => {"}}

